 import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, vec2, color, mix, smoothstep } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE, textureLoader, fontAtlas } = ctx;
  const { Group, PlaneGeometry, Mesh, Color, FrontSide } = THREE;

  const group = new Group();

  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {};
  const ink = colors.ink ?? '#16161d';
  const paper = colors.paper ?? '#e8ecf2';
  const surface = colors.surface ?? '#0b0b10';

  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const item = items.find(i => i.role === 'headline') || items[0] || { text: 'Features 3', typography: { fontSize: 39 } };

  const region = config.intent?.visualSpec?.atlasRegion ?? config.atlasRegion ?? { x: 0, y: 0, w: 512, h: 320 };
  const aspect = region.w / region.h;

  const refHeight = 0.34;
  const geo = new PlaneGeometry(refHeight * aspect, refHeight, 1, 1);

  const material = new MeshBasicNodeMaterial({
    side: FrontSide,
    transparent: false
  });
  material.color = new Color(surface);

  const gradientNode = mix(color(ink), color(surface), smoothstep(0.0, 1.0, uv().y));
  material.colorNode = gradientNode;

  const mesh = new Mesh(geo, material);
  group.add(mesh);

  const textObj = fontAtlas.createText(String(item.text || 'Features 3'), {
    fontSize: item.typography?.fontSize ?? 39,
    color: paper,
    align: 'center'
  });
  textObj.position.z = 0.025;
  group.add(textObj);

  group.onBeforeRender = (renderer, scene, camera) => {
    group.lookAt(camera.position);
  };

  let loadedTex = null;
  const url = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  if (url) {
    textureLoader.loadTexture(url).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.flipY = false;
      tex.needsUpdate = true;
      loadedTex = tex;

      const imgW = tex.image?.width || region.w;
      const imgH = tex.image?.height || region.h;
      const uOffset = region.x / imgW;
      const vOffset = region.y / imgH;
      const uScale = region.w / imgW;
      const vScale = region.h / imgH;

      const atlasUV = uv().add(vec2(uOffset, vOffset)).mul(vec2(uScale, vScale));
      const grain = texture(tex, atlasUV);

      material.colorNode = gradientNode.mul(grain.mul(0.22).add(0.89));
      material.mapNode = grain;
      material.needsUpdate = true;
    }).catch(() => {});
  }

  const timelines = [];

  group.userData.handlers = {};
  group.userData.cleanup = () => {
    timelines.forEach(t => t && typeof t.kill === 'function' && t.kill());
    if (loadedTex) loadedTex.dispose();
    material.dispose();
    geo.dispose();
    group.traverse((obj) => {
      if (obj.geometry && obj !== mesh) obj.geometry.dispose();
      if (obj.material && obj !== mesh) {
        if (Array.isArray(obj.material)) obj.material.forEach(m => m.dispose());
        else obj.material.dispose();
      }
    });
  };

  return group;
}
